import{_ as t,o,c as i,a5 as l}from"./chunks/framework.CsGesDJn.js";const n=JSON.parse('{"title":"Sequence Flow — Publish TikTok Video","description":"","frontmatter":{},"headers":[],"relativePath":"feature/publishing-social/3-8-14-publish-instagram-story/sequence-flow.md","filePath":"feature/publishing-social/3-8-14-publish-instagram-story/sequence-flow.md"}'),s={name:"feature/publishing-social/3-8-14-publish-instagram-story/sequence-flow.md"};function r(u,e,d,c,a,b){return o(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="sequence-flow-—-publish-tiktok-video" tabindex="-1">Sequence Flow — Publish TikTok Video <a class="header-anchor" href="#sequence-flow-—-publish-tiktok-video" aria-label="Permalink to &quot;Sequence Flow — Publish TikTok Video&quot;">​</a></h1><p>&gt; Supplements <code>spec.md</code> (FR 3.8.14). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly — it does not restate business rules (see spec.md for those).</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Scheduler (Job)</strong> — actor tương tác chính trong quy trình.</li><li><strong>Client</strong> — giao diện người dùng <code>Publish TikTok Video Page</code>.</li><li><strong>System</strong> — <code>PublishTikTokVideoController</code> / <code>PublishJobConsumer (Publisher Service)</code>.</li></ul><hr><h2 id="flow-a-—-luong-thuc-thi-chinh-publish-tiktok-video" tabindex="-1">Flow A — Luồng thực thi chính: Publish TikTok Video <a class="header-anchor" href="#flow-a-—-luong-thuc-thi-chinh-publish-tiktok-video" aria-label="Permalink to &quot;Flow A — Luồng thực thi chính: Publish TikTok Video&quot;">​</a></h2><ol><li>schedulerjob -&gt; schedulerserviceimpl: <code>triggerEveryMinute()</code></li><li>schedulerserviceimpl -&gt; postmongorepositoryb: <code>findScheduledPosts(scheduledAt &lt;= NOW(), status=&#39;SCHEDULED&#39;, platform=&#39;TIKTOK&#39;)</code></li><li>postmongorepositoryb --&gt; schedulerserviceimpl: <code>return List&lt;PostDocument&gt;</code></li><li>schedulerserviceimpl -&gt; postmongorepositoryb: <code>updateStatus(postId, &#39;IN_PROGRESS&#39;)</code></li><li>postmongorepositoryb --&gt; schedulerserviceimpl: <code>return 200 OK</code></li><li>schedulerserviceimpl -&gt; rabbitmqbrandhubpubl: <code>publish(&quot;brandhub.publishing&quot;, &quot;publish.job&quot;, PublishJobMessage {platform=&#39;TIKTOK&#39;, ...})</code></li><li>rabbitmqbrandhubpubl --&gt; schedulerserviceimpl: <code>return Acknowledgement</code></li><li>rabbitmqbrandhubpubl -&gt; publishjobconsumerpu: <code>consume(&quot;publisher.job.queue&quot;, message)</code></li><li>publishjobconsumerpu -&gt; publishjobconsumerpu: <code>checkRedisLockSETNX(&quot;processingPostIds:&quot; + postId, ttl=30m)</code></li><li>publishjobconsumerpu -&gt; tiktokpublishadapter: <code>publish(jobMessage)</code></li><li>tiktokpublishadapter -&gt; tiktokreelspublishse: <code>publish(jobMessage)</code></li><li>tiktokreelspublishse -&gt; tiktokreelspublishse: <code>rateLimiter.acquire() &amp; decryptToken(encryptedToken)</code></li><li>tiktokreelspublishse -&gt; s3mediastorage: <code>GET videoUrl (download video bytes)</code></li><li>s3mediastorage --&gt; tiktokreelspublishse: <code>return videoBytes (byte[])</code></li><li>tiktokreelspublishse -&gt; tiktokapi: <code>POST https://open.tiktokapis.com/v2/post/publish/video/init/ (post_info: caption, source_info: FILE_UPLOAD)</code></li><li>tiktokapi --&gt; tiktokreelspublishse: <code>return { publish_id: &quot;tiktok_pub_888&quot;, upload_url: &quot;https://...&quot; }</code></li><li>tiktokreelspublishse -&gt; tiktokapi: <code>PUT upload_url (videoBytes, Content-Type: video/mp4)</code></li><li>tiktokapi --&gt; tiktokreelspublishse: <code>return 200 OK (Uploaded)</code></li><li>tiktokreelspublishse --&gt; tiktokpublishadapter: <code>return PublishResult (status=&#39;SUCCESS&#39;, platformPostId=&#39;tiktok_pub_888&#39;)</code></li><li>tiktokpublishadapter --&gt; publishjobconsumerpu: <code>return PublishResult</code></li><li>publishjobconsumerpu -&gt; rabbitmqbrandhubpubl: <code>channel.basicAck(deliveryTag)</code></li><li>publishjobconsumerpu -&gt; rabbitmqbrandhubpubl: <code>publish(&quot;brandhub.publishing&quot;, &quot;publish.callback&quot;, CallbackMessage {status=&#39;SUCCESS&#39;, platformPostId=&#39;tiktok_pub_888&#39;})</code></li><li>rabbitmqbrandhubpubl --&gt; publishjobconsumerpu: <code>return ack</code></li><li>tiktokapi --&gt; tiktokreelspublishse: <code>return Error Response (Invalid token / Video spec error)</code></li><li>tiktokreelspublishse --&gt; tiktokpublishadapter: <code>return PublishResult (status=&#39;FAILED&#39;, errorCode, errorMessage)</code></li><li>tiktokpublishadapter --&gt; publishjobconsumerpu: <code>return throw Exception</code></li><li>publishjobconsumerpu -&gt; rabbitmqbrandhubpubl: <code>basicNack -&gt; Route to Dead Letter Queue (&quot;publisher.job.dlq&quot;)</code></li><li>rabbitmqbrandhubpubl --&gt; publishjobconsumerpu: <code>return ack</code></li><li>publishjobconsumerpu -&gt; rabbitmqbrandhubpubl: <code>publish(&quot;brandhub.publishing&quot;, &quot;publish.callback&quot;, CallbackMessage {status=&#39;FAILED&#39;, error})</code></li><li>rabbitmqbrandhubpubl --&gt; publishjobconsumerpu: <code>return ack</code></li><li>rabbitmqbrandhubpubl -&gt; publishcallbackconsu: <code>consume(&quot;business.publish_callback.queue&quot;, callbackMessage)</code></li><li>publishcallbackconsu -&gt; postmongorepositoryb: <code>updateStatus(postId, &#39;PUBLISHED&#39;, platformPostId)</code></li><li>postmongorepositoryb --&gt; publishcallbackconsu: <code>return 200 OK</code></li><li>publishcallbackconsu -&gt; postmongorepositoryb: <code>updateStatus(postId, &#39;FAILED&#39;, errorMessage)</code></li><li>postmongorepositoryb --&gt; publishcallbackconsu: <code>return 200 OK</code></li><li>publishcallbackconsu -&gt; rabbitmqbrandhubpubl: <code>channel.basicAck(deliveryTag)</code></li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>ErrorCode</th></tr></thead><tbody><tr><td>Xác thực</td><td>Token thiếu, hết hạn hoặc không hợp lệ</td><td>401</td><td><code>UNAUTHORIZED</code></td></tr><tr><td>Phân quyền</td><td>Vai trò người dùng không có quyền truy cập tính năng</td><td>403</td><td><code>FORBIDDEN</code></td></tr><tr><td>Kiểm tra dữ liệu</td><td>Dữ liệu đầu vào không hợp lệ hoặc xung đột trạng thái</td><td>400</td><td><code>BAD_REQUEST</code></td></tr><tr><td>Truy vấn</td><td>Không tìm thấy bản ghi đối tượng tương ứng</td><td>404</td><td><code>NOT_FOUND</code></td></tr></tbody></table>',10)])])}const p=t(s,[["render",r]]);export{n as __pageData,p as default};
